#!/usr/bin/env python3
"""
Fetch USGS streamflow data and NWS flood thresholds to identify flood days.
"""

import urllib.request
import json
import csv
from datetime import datetime, timedelta
import ssl
import time

# Create SSL context
ssl_context = ssl.create_default_context()

# Read station IDs
with open('/root/data/michigan_stations.txt', 'r') as f:
    stations = [line.strip() for line in f if line.strip()]

print(f"Found {len(stations)} USGS stations")

start_date = "2025-04-01"
end_date = "2025-04-07"

def fetch_url(url, timeout=60):
    """Fetch URL with proper headers and error handling"""
    try:
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (Python USGS Flood Analysis)',
            'Accept': 'application/json'
        })
        with urllib.request.urlopen(req, timeout=timeout, context=ssl_context) as response:
            return json.loads(response.read().decode('utf-8'))
    except Exception as e:
        return None

# Step 1: Get NWS gauge information with flood thresholds
print("\nStep 1: Fetching NWS gauge information with flood thresholds...")

nws_url = "https://api.water.noaa.gov/nwps/v1/gauges"
nws_data = fetch_url(nws_url)

# Build mapping of USGS site numbers to NWS gauges with flood thresholds
usgs_to_nws = {}
nws_gauge_ids = []

if nws_data and 'gauges' in nws_data:
    # Filter for Michigan gauges
    mi_gauges = [g for g in nws_data['gauges'] if g.get('state', {}).get('abbreviation') == 'MI']
    print(f"  Found {len(mi_gauges)} Michigan gauges in NWS data")
    nws_gauge_ids = [g['lid'] for g in mi_gauges]

# Step 2: Get detailed info for each NWS gauge including USGS ID and flood stages
print("\nStep 2: Fetching flood thresholds for NWS gauges...")

flood_thresholds = {}  # USGS site -> {action, minor, moderate, major}

for i, lid in enumerate(nws_gauge_ids):
    if i % 20 == 0:
        print(f"  Processing gauge {i+1}/{len(nws_gauge_ids)}...")

    gauge_url = f"https://api.water.noaa.gov/nwps/v1/gauges/{lid}"
    gauge_data = fetch_url(gauge_url, timeout=30)

    if gauge_data:
        # Get USGS ID if available
        usgs_id = gauge_data.get('usgsId', '')

        # Get flood categories/thresholds
        flood = gauge_data.get('flood', {})

        if usgs_id and flood:
            thresholds = {}
            categories = flood.get('categories', [])
            for cat in categories:
                name = cat.get('name', '').lower()
                stage = cat.get('stage')
                flow = cat.get('flow')

                if name in ['action', 'minor', 'moderate', 'major']:
                    if stage is not None and stage > 0:
                        thresholds[f'{name}_stage'] = stage
                    if flow is not None and flow > 0:
                        thresholds[f'{name}_flow'] = flow

            if thresholds:
                flood_thresholds[usgs_id] = thresholds
                if usgs_id in stations:
                    print(f"    {usgs_id}: {thresholds}")

    time.sleep(0.05)  # Be nice to the API

print(f"\n  Got flood thresholds for {len(flood_thresholds)} sites")

# Filter to only our stations
our_thresholds = {k: v for k, v in flood_thresholds.items() if k in stations}
print(f"  {len(our_thresholds)} of our stations have flood thresholds")

# Step 3: Fetch USGS daily values for our stations
print("\nStep 3: Fetching USGS streamflow data...")

# Get both discharge (00060) and gage height (00065)
all_data = {}  # station -> {param -> [(date, value), ...]}

batch_size = 30
for i in range(0, len(stations), batch_size):
    batch = stations[i:i+batch_size]
    sites_str = ",".join(batch)
    print(f"  Batch {i//batch_size + 1}: stations {i+1}-{min(i+batch_size, len(stations))}")

    # Get discharge data
    url = f"https://waterservices.usgs.gov/nwis/dv/?format=json&sites={sites_str}&startDT={start_date}&endDT={end_date}&parameterCd=00060,00065&siteStatus=all"
    data = fetch_url(url)

    if data and 'value' in data and 'timeSeries' in data['value']:
        for ts in data['value']['timeSeries']:
            site_no = ts['sourceInfo']['siteCode'][0]['value']
            param = ts['variable']['variableCode'][0]['value']

            if site_no not in all_data:
                all_data[site_no] = {}

            values = []
            for vs in ts['values']:
                for v in vs['value']:
                    try:
                        val = float(v['value'])
                        date = v['dateTime'][:10]
                        values.append((date, val))
                    except:
                        pass

            if values:
                all_data[site_no][param] = values

print(f"\n  Got data for {len(all_data)} stations")

# Step 4: Analyze for flooding
print("\nStep 4: Analyzing for flood conditions...")

flood_results = {}

for site_no, data in all_data.items():
    flood_days = 0

    if site_no in our_thresholds:
        thresholds = our_thresholds[site_no]

        # Check gage height against stage thresholds
        if '00065' in data:
            for name in ['action_stage', 'minor_stage', 'moderate_stage', 'major_stage']:
                if name in thresholds:
                    threshold = thresholds[name]
                    for date, val in data['00065']:
                        if val >= threshold:
                            flood_days += 1
                    break  # Use first available threshold

        # If no stage data, check discharge against flow thresholds
        if flood_days == 0 and '00060' in data:
            for name in ['action_flow', 'minor_flow', 'moderate_flow', 'major_flow']:
                if name in thresholds:
                    threshold = thresholds[name]
                    for date, val in data['00060']:
                        if val >= threshold:
                            flood_days += 1
                    break

    if flood_days > 0:
        flood_results[site_no] = flood_days
        print(f"  {site_no}: {flood_days} flood days")

# If we didn't find many floods with thresholds, try percentile-based approach
if len(flood_results) < 3:
    print("\n  Trying percentile-based flood detection...")

    # Get historical statistics for comparison
    for site_no, data in all_data.items():
        if site_no in flood_results:
            continue

        # Get daily statistics for this site
        stat_url = f"https://waterservices.usgs.gov/nwis/stat/?format=json&sites={site_no}&statReportType=daily&statTypeCd=P90&parameterCd=00060"
        stat_data = fetch_url(stat_url, timeout=30)

        if stat_data and 'value' in stat_data and 'timeSeries' in stat_data['value']:
            # Get P90 values for April 1-7
            p90_values = {}
            for ts in stat_data['value']['timeSeries']:
                for vs in ts['values']:
                    for v in vs['value']:
                        try:
                            month = int(v.get('month', 0))
                            day = int(v.get('day', 0))
                            if month == 4 and 1 <= day <= 7:
                                p90_values[(month, day)] = float(v['value'])
                        except:
                            pass

            if p90_values and '00060' in data:
                # Compare current values to P90
                flood_days = 0
                for date, val in data['00060']:
                    m = int(date[5:7])
                    d = int(date[8:10])
                    p90 = p90_values.get((m, d))
                    if p90 and val > p90:
                        flood_days += 1

                if flood_days > 0:
                    flood_results[site_no] = flood_days
                    print(f"  {site_no}: {flood_days} days above P90")

print("\n" + "=" * 60)
print(f"RESULTS: Found {len(flood_results)} stations with flooding")
print("=" * 60)

# Write results
with open('/root/output/flood_results.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    for station_id in sorted(flood_results.keys()):
        writer.writerow([station_id, flood_results[station_id]])

print(f"\nResults written to /root/output/flood_results.csv")

if flood_results:
    print("\nStations with flooding:")
    for sid in sorted(flood_results.keys()):
        print(f"  {sid}: {flood_results[sid]} days")
else:
    print("\nNo flooding detected in the specified period.")

